"""Bit-level building blocks for the stream codec."""

class InvalidStream(Exception):
    pass

class EndOfStream(InvalidStream):
    pass

class BitReader:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos

    def read(self, n):
        p = self.pos
        if p + n > len(self.data) * 8:
            raise EndOfStream()
        self.pos += n
        if not n:
            return 0
        a = p >> 3
        b = (p + n + 7) >> 3
        return (int.from_bytes(self.data[a:b], 'little') >> (p & 7)) & ((1 << n) - 1)

    def align(self, check=True):
        n = (-self.pos) & 7
        v = self.read(n)
        if check and v:
            raise InvalidStream('nonzero padding')

    def bytes(self, n):
        if self.pos & 7:
            raise InvalidStream('unaligned byte read')
        s = self.pos >> 3
        self.pos += n * 8
        if s + n > len(self.data):
            self.pos = len(self.data) * 8
            raise EndOfStream()
        return self.data[s:s+n]

class BitWriter:
    def __init__(self):
        self.data = bytearray()
        self.pos = 0

    def write(self, n, val):
        if not n:
            return
        val &= (1 << n) - 1
        shift = self.pos & 7
        at = self.pos >> 3
        self.pos += n
        need = (self.pos + 7) >> 3
        self.data.extend(b'\0' * (need - len(self.data)))
        val <<= shift
        for i in range(at, need):
            self.data[i] |= val & 255
            val >>= 8

    def align(self):
        self.write((-self.pos) & 7, 0)

    def bytes(self, data):
        self.align()
        self.data.extend(data)
        self.pos += len(data)*8

    def finish(self):
        return bytes(self.data)


def read_uint8(r):
    if r.read(1) == 0:
        return 0
    n = r.read(3)
    return 1 if n == 0 else (1 << n) + r.read(n)


def write_uint8(w, v):
    if v == 0:
        w.write(1, 0)
    else:
        w.write(1, 1)
        n = v.bit_length() - 1
        w.write(3, n)
        w.write(n, v - (1 << n))


def reverse(v, n):
    q = 0
    for _ in range(n):
        q = (q << 1) | (v & 1)
        v >>= 1
    return q

class Huffman:
    def __init__(self, lengths=None, singleton=None):
        self.single = singleton
        self.codes = {}
        self.decode = {}
        if singleton is not None:
            self.codes[singleton] = (0, 0)
            self.maxbits = 0
            return
        nonzero = [i for i, x in enumerate(lengths) if x]
        if len(nonzero) == 1:
            self.single = nonzero[0]
            self.codes[self.single] = (0, 0)
            self.maxbits = 0
            return
        if not nonzero:
            raise InvalidStream('empty code')
        self.maxbits = max(lengths)
        counts = [0] * (self.maxbits + 1)
        for x in lengths:
            if x:
                counts[x] += 1
        code = 0
        start = [0] * (self.maxbits + 1)
        for n in range(1, self.maxbits + 1):
            code = (code + counts[n-1]) << 1
            start[n] = code
        if code + counts[-1] != (1 << self.maxbits):
            raise InvalidStream('invalid prefix tree')
        for sym, n in enumerate(lengths):
            if n:
                b = reverse(start[n], n)
                start[n] += 1
                self.codes[sym] = (n, b)
                self.decode[n, b] = sym

    def read(self, r):
        if self.single is not None:
            return self.single
        bits = 0
        for i in range(1, self.maxbits + 1):
            bits |= r.read(1) << (i-1)
            sym = self.decode.get((i, bits))
            if sym is not None:
                return sym
        raise InvalidStream('invalid code')

    def write(self, w, sym):
        n, b = self.codes[sym]
        w.write(n, b)

CL_ORDER = [1,2,3,4,0,5,17,6,16,7,8,9,10,11,12,13,14,15]
CL_LENGTHS = [2,4,3,2,2,4]
CL_CODES = [0,7,3,2,1,15]


def read_tree(r, alphabet):
    kind = r.read(2)
    if kind == 1:
        n = r.read(2) + 1
        symbols = [r.read((alphabet-1).bit_length()) for _ in range(n)]
        if len(set(symbols)) != n or any(x >= alphabet for x in symbols):
            raise InvalidStream('bad simple tree')
        if n == 1:
            return Huffman(singleton=symbols[0])
        ls = [1,1] if n == 2 else [1,2,2] if n == 3 else ([1,2,3,3] if r.read(1) else [2,2,2,2])
        lengths = [0] * alphabet
        for s, l in zip(symbols, ls):
            lengths[s] = l
        return Huffman(lengths)
    cls = [0] * 18
    space = 32
    for i in range(kind, 18):
        v = r.read(2)
        if v == 0:
            n = 0
        elif v == 1:
            n = 4
        elif v == 2:
            n = 3
        elif r.read(1) == 0:
            n = 2
        else:
            n = 5 if r.read(1) else 1
        cls[CL_ORDER[i]] = n
        if n:
            space -= 32 >> n
            if space <= 0:
                break
    if space < 0 or (space != 0 and sum(bool(x) for x in cls) != 1):
        raise InvalidStream('bad code length tree')
    tree = Huffman(cls)
    lengths = []
    prev = 8
    repeat = 0
    repeated_len = 0
    space = 32768
    while len(lengths) < alphabet and space > 0:
        c = tree.read(r)
        if c < 16:
            repeat = 0
            lengths.append(c)
            if c:
                prev = c
                space -= 32768 >> c
        else:
            v = prev if c == 16 else 0
            nb = c - 14
            if v != repeated_len:
                repeat = 0
                repeated_len = v
            old = repeat
            repeat = ((repeat - 2) << nb) if repeat else 0
            repeat += r.read(nb) + 3
            count = repeat - old
            if len(lengths) + count > alphabet:
                raise InvalidStream('length repeat overflow')
            lengths += [v] * count
            if v:
                space -= count * (32768 >> v)
    if space != 0:
        raise InvalidStream('incomplete alphabet')
    lengths += [0] * (alphabet - len(lengths))
    return Huffman(lengths)


def write_simple(w, alphabet, symbols, skew=False):
    w.write(2, 1)
    w.write(2, len(symbols)-1)
    for s in symbols:
        w.write((alphabet-1).bit_length(), s)
    if len(symbols) == 4:
        w.write(1, int(skew))
    if len(symbols) == 1:
        return Huffman(singleton=symbols[0])
    lens = [1,1] if len(symbols) == 2 else [1,2,2] if len(symbols) == 3 else [1,2,3,3] if skew else [2,2,2,2]
    lengths = [0] * alphabet
    for s,l in zip(symbols,lens):
        lengths[s] = l
    return Huffman(lengths)
