import heapq
import math
from collections import Counter, defaultdict
from codec import *
from fast_tables import FIXED_TREES


def make_lengths(counts, limit=15):
    used = [i for i,n in enumerate(counts) if n]
    if len(used) < 2:
        return [int(bool(n)) for n in counts]
