        if q<=1:
            ds=distance_code(dist,cache,short=False)[0]
            if dist==cache[0]:ds=0
            commands.append((lit,insert,2,dist,False))
            if best>2:
                commands.append((pos+2,0,best-2,dist,False))
        else:
            commands.append((lit,insert,best,dist,False))
        if dist!=cache[0]:cache=[dist]+cache[:3]
