def encode_commands(data,commands,q,window,comment=b'', context_info=None):
    w=BitWriter()
    write_window(w,window)
    write_comment(w,comment)
    write_header(w,len(data),last=q>=2)
    if q<2:w.write(1,0) if False else None
    postfix,direct=(3,120) if q>=10 else (0,0)
    alph=16+direct+((124 if window>24 else 48)<<postfix)
    cache=[4,11,15,16]
    parsed=[]
    litcounts=[0]*256
    cmdcounts=[0]*704
    distcounts=[0]*alph
    for start,ins,copy,dist,static in commands:
        dc,nb,extra=(0,0,0) if dist is None else distance_code(dist,cache,postfix,direct,short=(not static and q>=2))
        if q<=1 and dist==cache[0]:dc,nb,extra=0,0,0
        cmd,ic,cc=command_code(ins,copy,dc==0 and dist is not None)
        cmdcounts[cmd]+=1
        if cmd>=128 and dist is not None:distcounts[dc]+=1
        for c in data[start:start+ins]:litcounts[c]+=1
        parsed.append((start,ins,copy,cmd,ic,cc,dc,nb,extra,dist))
        if dist is not None and dc!=0 and not static:
            cache=[dist]+cache[:3]
    w.write(3,0)
    w.write(2,postfix);w.write(4,direct>>postfix)
    w.write(2,2 if q>=4 else 0)
    w.write(1,0);w.write(1,0)
    lt=write_tree(w,litcounts,fast=q<=2)
    if q in [0,2]:
        ct=fixed_tree(w,q,0,704)
        dt=fixed_tree(w,q,1,alph)
    else:
        if q==1:
            cmdcounts[136]+=1;cmdcounts[144]+=1;distcounts[20]+=1
        ct=write_tree(w,cmdcounts,force_complex=q==1)
        dt=write_tree(w,distcounts,force_complex=q==1)
    for start,ins,copy,cmd,ic,cc,dc,nb,extra,dist in parsed:
        ct.write(w,cmd)
        w.write(INSERT_BITS[ic],ins-INSERT_BASE[ic])
        w.write(COPY_BITS[cc],copy-COPY_BASE[cc])
        for c in data[start:start+ins]:lt.write(w,c)
        if dist is not None and cmd>=128:
            dt.write(w,dc)
            w.write(nb,extra)
    if q<=1:write_header(w,0,True)
    return w.finish()


def compress(data, quality=11, window=24, comment=b'', dictionary=b''):
    raw=encode_raw(data,window,comment)
    if not data or len(data)<4:
        return raw
    cmds=greedy_commands(data,quality,dictionary)
    try:
        packed=encode_commands(data,cmds,quality,window,comment)
    except (KeyError, ValueError, InvalidStream):
        return raw
    if len(packed)>len(raw):
        return raw
    return packed
