class UsageError(Exception):
    pass

class EarlyExit(Exception):
    def __init__(self, kind):
        self.kind=kind

@dataclass
class Options:
    mode: str = 'compress'
    command_set: bool = False
    quality: int = 11
    window: int = 0
    large: bool = False
    force: bool = False
    stdout: bool = False
    output: object = None
    suffix: str = '.br'
    remove: bool = False
    squash: bool = False
    no_stat: bool = False
    verbose: bool = False
    concatenated: bool = False
    comment: bytes = b''
    dictionary: object = None
    files: list = field(default_factory=list)


def decode_base64(text):
    bits=0;num=0
    out=bytearray()
    padding=0
    alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    for c in text:
        if c in ' \t\r\n\v\f':
            continue
        if c=='=':
            padding+=1
            if padding>2:raise UsageError('invalid base64-encoded comment')
            continue
        if padding:raise UsageError('invalid base64-encoded comment')
        c='+' if c=='-' else '/' if c=='_' else c
        n=alphabet.find(c)
        if n<0:raise UsageError('invalid base64-encoded comment')
        num=(num<<6)|n
        bits+=6
        if bits>=8:
            bits-=8
            out.append((num>>bits)&255)
            if len(out)>80:raise UsageError('invalid base64-encoded comment')
    return bytes(out)


def parse(program,args):
    opt=Options()
    seen=set()
    alias=program.split('.')[0]
    if alias in ['unbrotli','brcat']:
        opt.mode='decompress';opt.command_set=True
    if alias=='brcat':
        opt.stdout=True;opt.concatenated=True
        seen.update(['stdout','concatenated'])
    flags={'c':'stdout','d':'decompress','f':'force','h':'help','j':'rm','s':'squash','k':'keep','n':'no-copy-stat','t':'test','v':'verbose','K':'concatenated','V':'version','Z':'best'}
    params={'o':'output','q':'quality','w':'lgwin','C':'comment','D':'dictionary','S':'suffix'}
    dup={
      'stdout':'write to standard output already set',
      'force':'force output overwrite already set',
      'remove':'argument --rm / -j or --keep / -k already set',
      'squash':'argument --squash / -s already set',
      'no-copy-stat':'argument --no-copy-stat / -n already set',
      'verbose':'argument --verbose / -v already set',
      'concatenated':'argument -K / --concatenated already set',
      'quality':'quality already set',
      'lgwin':'lgwin parameter already set',
      'comment':'comment already set',
      'dictionary':'dictionary path already set',
      'suffix':'suffix already set'
    }
    def mark(key):
        if key in seen:raise UsageError(dup[key])
        seen.add(key)
    def number(value,kind,maximum):
        if not re.fullmatch(r'0|[1-9][0-9]*',value) or len(value)>2 or int(value)>maximum:
            raise UsageError('error parsing '+kind+' value ['+value+']')
        return int(value)
    def set_option(name,value,spelling):
        if name in ['help','version']:raise EarlyExit(name)
        if name in ['decompress','test']:
            if opt.command_set:raise UsageError('command already set when parsing '+spelling)
            opt.command_set=True;opt.mode=name
        elif name=='output':
            if opt.stdout:raise UsageError('write to standard output already set ('+spelling+')')
            opt.output=value
        elif name in ['rm','keep']:
            mark('remove');opt.remove=name=='rm'
        elif name in ['best','quality']:
            mark('quality');opt.quality=11 if name=='best' else number(value,'quality',11)
        elif name in ['lgwin','large_window']:
            mark('lgwin');opt.window=number(value,'lgwin',30 if name=='large_window' else 24)
            if 0<opt.window<10:raise UsageError('lgwin parameter ('+str(opt.window)+') smaller than the minimum (10)')
            opt.large=name=='large_window'
        elif name=='comment':
            mark(name);opt.comment=decode_base64(value)
        elif name=='dictionary':
            mark(name);opt.dictionary=value
        elif name=='suffix':
            mark(name);opt.suffix=value
        else:
            mark(name)
            setattr(opt,{'no-copy-stat':'no_stat'}.get(name,name),True)
    i=0;ended=False
    while i<len(args):
        arg=args[i];i+=1
        if ended or not arg.startswith('-') or arg=='-':
            opt.files.append(arg);continue
        if arg=='--':
            ended=True;continue
        if arg.startswith('--'):
            name=arg[2:]
            if name in flags.values():
                set_option(name,None,arg)
                continue
            if '=' not in name or not name.split('=',1)[1]:
                raise UsageError('must pass the parameter as '+arg+'=value')
            short,value=name.split('=',1)
            candidates=['comment','dictionary','output','quality','lgwin','large_window','suffix']
            key=next((c for c in candidates if c.startswith(short)),None)
            if key is None:raise UsageError('invalid parameter: ['+name+']')
            set_option(key,value,'--'+key)
            continue
        for k,c in enumerate(arg[1:],1):
            if c in '0123456789':
                set_option('quality',c,'-'+c)
            elif c in params:
                if k!=len(arg)-1 or i>=len(args) or not args[i]:
                    raise UsageError('expected parameter for argument -'+c)
                value=args[i];i+=1
                set_option(params[c],value,'-'+c)
            elif c in flags:
                set_option(flags[c],None,'-'+c)
            else:
                raise UsageError('invalid argument -'+c)
    if '/' in opt.suffix or '\\' in opt.suffix:
        raise UsageError('')
    if opt.mode=='test' and (opt.output is not None or opt.stdout):
        raise UsageError('')
    if opt.squash and opt.stdout:
        raise UsageError('')
    if opt.concatenated and (opt.mode!='decompress' or opt.comment):
        raise UsageError('')
    return opt


def human_size(n):
    units=['B','KiB','MiB','GiB','TiB']
    if n<1024:return str(n)+' B'
    size=float(n);j=0
    while size>=1024 and j<len(units)-1:
        size/=1024;j+=1
    return format(size,'.3f')+' '+units[j]


