    descriptions={
      'nonzero padding':('FORMAT_PADDING_2',15),
      'raw padding':('FORMAT_PADDING_1',14),
      'metadata leading zero':('FORMAT_EXUBERANT_META_NIBBLE',3),
      'metablock leading zero':('FORMAT_EXUBERANT_NIBBLE',1),
      'reserved metadata bit':('FORMAT_RESERVED',2),
      'bad simple tree':('FORMAT_SIMPLE_HUFFMAN_ALPHABET',4),
      'duplicate simple symbols':('FORMAT_SIMPLE_HUFFMAN_SAME',5),
      'bad code length tree':('FORMAT_CL_SPACE',6),
      'empty code':('FORMAT_CL_SPACE',6),
      'invalid prefix tree':('FORMAT_HUFFMAN_SPACE',7),
      'incomplete alphabet':('FORMAT_HUFFMAN_SPACE',7),
      'length repeat overflow':('FORMAT_HUFFMAN_SPACE',7),
      'context repeat overflow':('FORMAT_CONTEXT_MAP_REPEAT',8),
      'insert beyond metablock':('FORMAT_BLOCK_LENGTH_1',9),
      'copy beyond metablock':('FORMAT_BLOCK_LENGTH_2',10),
      'word beyond metablock':('FORMAT_BLOCK_LENGTH_2',10),
      'bad dictionary transform':('FORMAT_TRANSFORM',11),
      'bad dictionary length':('FORMAT_DICTIONARY',12),
      'bad large window':('FORMAT_WINDOW_BITS',13),
      'invalid window':('FORMAT_WINDOW_BITS',13),
      'invalid backward distance':('FORMAT_DISTANCE',16),
      'distance beyond output':('FORMAT_DISTANCE',16),
    }
    v=descriptions.get(name,('FORMAT_HUFFMAN_SPACE',7))
    return v[0]+' (-'+str(v[1])+')'


def main(program=None,args=None):
    if program is None:program=sys.argv[0]
    if args is None:args=sys.argv[1:]
    program=program.replace('\\','/').split('/')[-1]
