class EarlyExit(Exception):
    def __init__(self, kind):
        self.kind=kind

@dataclass
class Options:
    mode: str = 'compress'
    command_set: bool = False
    quality: int = 11
    window: int = 0
    large: bool = False
    force: bool = False
    stdout: bool = False
    output: object = None
    suffix: str = '.br'
    remove: bool = False
    squash: bool = False
    no_stat: bool = False
    verbose: bool = False
    concatenated: bool = False
    comment: bytes = b''
    dictionary: object = None
    files: list = field(default_factory=list)


def decode_base64(text):
    bits=0;num=0
    out=bytearray()
    padding=0
    alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    for c in text:
        if c in ' \t\r\n\v\f':
            continue
        if c=='=':
            padding+=1
            if padding>2:raise UsageError('invalid base64-encoded comment')
            continue
        if padding:raise UsageError('invalid base64-encoded comment')
        c='+' if c=='-' else '/' if c=='_' else c
        n=alphabet.find(c)
        if n<0:raise UsageError('invalid base64-encoded comment')
        num=(num<<6)|n
        bits+=6
        if bits>=8:
            bits-=8
            out.append((num>>bits)&255)
            if len(out)>80:raise UsageError('invalid base64-encoded comment')
    return bytes(out)


def parse(program,args):
    opt=Options()
    seen=set()
    alias=program.split('.')[0]
    if alias in ['unbrotli','brcat']:
        opt.mode='decompress';opt.command_set=True
    if alias=='brcat':
        opt.stdout=True;opt.concatenated=True
        seen.update(['stdout','concatenated'])
    flags={'c':'stdout','d':'decompress','f':'force','h':'help','j':'rm','s':'squash','k':'keep','n':'no-copy-stat','t':'test','v':'verbose','K':'concatenated','V':'version','Z':'best'}
    params={'o':'output','q':'quality','w':'lgwin','C':'comment','D':'dictionary','S':'suffix'}
    dup={
      'stdout':'write to standard output already set',
      'force':'force output overwrite already set',
      'remove':'argument --rm / -j or --keep / -k already set',
      'squash':'argument --squash / -s already set',
      'no-copy-stat':'argument --no-copy-stat / -n already set',
      'verbose':'argument --verbose / -v already set',
      'concatenated':'argument -K / --concatenated already set',
      'quality':'quality already set',
      'lgwin':'lgwin parameter already set',
      'comment':'comment already set',
      'dictionary':'dictionary path already set',
      'suffix':'suffix already set'
    }
    def mark(key):
        if key in seen:raise UsageError(dup[key])
        seen.add(key)
    def number(value,kind,maximum):
        if not re.fullmatch(r'0|[1-9][0-9]*',value) or len(value)>2 or int(value)>maximum:
            raise UsageError('error parsing '+kind+' value ['+value+']')
        return int(value)
    def set_option(name,value,spelling):
        if name in ['help','version']:raise EarlyExit(name)
        if name in ['decompress','test']:
            if opt.command_set:raise UsageError('command already set when parsing '+spelling)
            opt.command_set=True;opt.mode=name
        elif name=='output':
            if opt.stdout:raise UsageError('write to standard output already set ('+spelling+')')
            opt.output=value
        elif name in ['rm','keep']:
            mark('remove');opt.remove=name=='rm'
        elif name in ['best','quality']:
            mark('quality');opt.quality=11 if name=='best' else number(value,'quality',11)
        elif name in ['lgwin','large_window']:
            mark('lgwin');opt.window=number(value,'lgwin',30 if name=='large_window' else 24)
            if 0<opt.window<10:raise UsageError('lgwin parameter ('+str(opt.window)+') smaller than the minimum (10)')
            opt.large=name=='large_window'
        elif name=='comment':
            mark(name);opt.comment=decode_base64(value)
        elif name=='dictionary':
            mark(name);opt.dictionary=value
        elif name=='suffix':
            mark(name);opt.suffix=value
        else:
            mark(name)
            setattr(opt,{'no-copy-stat':'no_stat'}.get(name,name),True)
    i=0;ended=False
    while i<len(args):
        arg=args[i];i+=1
        if ended or not arg.startswith('-') or arg=='-':
            opt.files.append(arg);continue
        if arg=='--':
            ended=True;continue
        if arg.startswith('--'):
            name=arg[2:]
            if name in flags.values():
                set_option(name,None,arg)
                continue
            if '=' not in name or not name.split('=',1)[1]:
                raise UsageError('must pass the parameter as '+arg+'=value')
            short,value=name.split('=',1)
            candidates=['comment','dictionary','output','quality','lgwin','large_window','suffix']
            key=next((c for c in candidates if c.startswith(short)),None)
            if key is None:raise UsageError('invalid parameter: ['+name+']')
            set_option(key,value,'--'+key)
            continue
        for k,c in enumerate(arg[1:],1):
            if c in '0123456789':
                set_option('quality',c,'-'+c)
            elif c in params:
                if k!=len(arg)-1 or i>=len(args) or not args[i]:
                    raise UsageError('expected parameter for argument -'+c)
                value=args[i];i+=1
                set_option(params[c],value,'-'+c)
            elif c in flags:
                set_option(flags[c],None,'-'+c)
            else:
                raise UsageError('invalid argument -'+c)
    if '/' in opt.suffix or '\\' in opt.suffix:
        raise UsageError('')
    if opt.mode=='test' and (opt.output is not None or opt.stdout):
        raise UsageError('')
    if opt.squash and opt.stdout:
        raise UsageError('')
    if opt.concatenated and (opt.mode!='decompress' or opt.comment):
        raise UsageError('')
    return opt


def human_size(n):
    units=['B','KiB','MiB','GiB','TiB']
    if n<1024:return str(n)+' B'
    size=float(n);j=0
    while size>=1024 and j<len(units)-1:
        size/=1024;j+=1
    return format(size,'.3f')+' '+units[j]


def reason(error):
    if isinstance(error,EndOfStream):return 'truncated input'
    name=str(error)
    descriptions={
      'nonzero padding':('FORMAT_PADDING_2',15),
      'raw padding':('FORMAT_PADDING_1',14),
      'metadata leading zero':('FORMAT_EXUBERANT_META_NIBBLE',3),
      'metablock leading zero':('FORMAT_EXUBERANT_NIBBLE',1),
      'reserved metadata bit':('FORMAT_RESERVED',2),
      'bad simple tree':('FORMAT_SIMPLE_HUFFMAN_ALPHABET',4),
      'duplicate simple symbols':('FORMAT_SIMPLE_HUFFMAN_SAME',5),
      'bad code length tree':('FORMAT_CL_SPACE',6),
      'empty code':('FORMAT_CL_SPACE',6),
      'invalid prefix tree':('FORMAT_HUFFMAN_SPACE',7),
      'incomplete alphabet':('FORMAT_HUFFMAN_SPACE',7),
      'length repeat overflow':('FORMAT_HUFFMAN_SPACE',7),
      'context repeat overflow':('FORMAT_CONTEXT_MAP_REPEAT',8),
      'insert beyond metablock':('FORMAT_BLOCK_LENGTH_1',9),
      'copy beyond metablock':('FORMAT_BLOCK_LENGTH_2',10),
      'word beyond metablock':('FORMAT_BLOCK_LENGTH_2',10),
      'bad dictionary transform':('FORMAT_TRANSFORM',11),
      'bad dictionary length':('FORMAT_DICTIONARY',12),
      'bad large window':('FORMAT_WINDOW_BITS',13),
      'invalid window':('FORMAT_WINDOW_BITS',13),
      'invalid backward distance':('FORMAT_DISTANCE',16),
      'distance beyond output':('FORMAT_DISTANCE',16),
    }
    v=descriptions.get(name,('FORMAT_HUFFMAN_SPACE',7))
    return v[0]+' (-'+str(v[1])+')'


def main(program=None,args=None):
    if program is None:program=sys.argv[0]
    if args is None:args=sys.argv[1:]
    program=program.replace('\\','/').split('/')[-1]
    helptext=HELP.format(program=program)
    def err(s):
        try:sys.stderr.write(s+'\n');sys.stderr.flush()
        except OSError:pass
    try:
        opt=parse(program,args)
    except UsageError as e:
        if str(e):err(str(e))
        sys.stdout.write(helptext)
        return 1
    except EarlyExit as e:
        if e.kind=='version':sys.stdout.write('brotli 1.2.0\n')
        else:sys.stderr.write(helptext)
        return 0
    dictionary=b''
    if opt.dictionary is not None:
        try:
            fd=os.open(opt.dictionary,os.O_RDONLY)
        except OSError as e:
            err('failed to open dictionary file ['+opt.dictionary+']: '+e.strerror)
            return 1
        try:
            chunks=[]
            while True:
                b=os.read(fd,524288)
                if not b:break
                chunks.append(b)
            dictionary=b''.join(chunks)
        except OSError:
            pass
        os.close(fd)
    files=opt.files or ['-']
    used_stdin=False
    for name in files:
        input_name=None if name=='-' else name
        label=input_name if input_name is not None else 'con'
        output_name=opt.output
        if opt.mode=='test':output_name=None
        elif output_name is None and not opt.stdout and input_name is not None:
            if opt.mode=='compress':output_name=name+opt.suffix
            else:
                base=name.replace('\\','/').split('/')[-1]
                if len(base)<=len(opt.suffix):
                    err('empty output file name for ['+name+'] input file');return 1
                if not name.endswith(opt.suffix):
                    err('input file ['+name+'] suffix mismatch');return 1
                output_name=name[:-len(opt.suffix)]
        fdin=None;fdout=None;info=None
        if input_name is not None:
            try:
                fdin=os.open(input_name,os.O_RDONLY)
                info=os.fstat(fdin)
            except OSError as e:
                err('failed to open input file ['+input_name+']: '+e.strerror)
                return 1
        else:
            if used_stdin:
                os.kill(os.getpid(),signal.SIGSEGV)
            used_stdin=True;fdin=0
        if not opt.force and opt.mode!='compress' and input_name is None and os.isatty(0):
            err('Use -h help. Use -f to force input from a terminal.')
            return 1
        if not opt.force and opt.mode=='compress' and output_name is None and os.isatty(1):
            err('Use -h help. Use -f to force output to a terminal.')
            if input_name is not None:os.close(fdin)
            return 1
        if opt.mode!='test' and output_name is not None:
            try:
                flags=os.O_WRONLY|os.O_CREAT|(os.O_TRUNC if opt.force else os.O_EXCL)
                fdout=os.open(output_name,flags,0o600)
            except OSError as e:
                err('failed to open output file ['+output_name+']: '+e.strerror)
                if input_name is not None:os.close(fdin)
                return 1
        def discard():
            nonlocal fdout
            if fdout is not None:
                try:os.close(fdout)
                except OSError:pass
                fdout=None
                try:os.unlink(output_name)
                except OSError:pass
        try:
            chunks=[]
            while True:
                b=os.read(fdin,524288)
                if not b:break
                chunks.append(b)
            data=b''.join(chunks)
        except OSError as e:
            err('failed to read input ['+label+']: '+e.strerror)
            discard()
            if input_name is not None:os.close(fdin)
            return 1
        if input_name is not None:os.close(fdin)
        failure=None;missing_comment=False
        if opt.mode=='compress':
            window=opt.window
            if window==0:
                if info is not None and stat.S_ISREG(info.st_mode):
                    window=min(24,max(10,(max(info.st_size,0)+15).bit_length()))
                else:window=24
            if opt.quality<2:window=max(18,window)
            output=compress(data,opt.quality,window,opt.comment,dictionary)
        else:
            pieces=[];at=0
            while True:
                decoder=Decoder(data[at:],dictionary).run()
                if opt.comment and decoder.comments and decoder.comments[0]!=opt.comment:
                    failure='comment mismatch';break
                if opt.comment and not decoder.comments:missing_comment=True
                pieces.append(bytes(decoder.out))
                if not decoder.success:
                    failure=reason(decoder.error);break
                at+=decoder.consumed
                if at==len(data):break
                if not opt.concatenated:
                    failure='extra input';break
            output=b''.join(pieces)
        if opt.mode!='test':
            try:
                dest=fdout if fdout is not None else 1
                view=memoryview(output)
                while view:
                    n=os.write(dest,view)
                    view=view[n:]
            except OSError as e:
                err('failed to write output ['+(output_name or 'con')+']: '+e.strerror)
                discard();return 1
        if failure is not None:
            err('corrupt input ['+label+']')
            if opt.verbose:err('reason: '+failure)
            discard()
            return 1
        if opt.verbose:
            action='Compressed' if opt.mode=='compress' else 'Decompressed'
            err(action+' ['+label+']: '+human_size(len(data))+' -> '+human_size(len(output))+' in 0.00 sec')
        if missing_comment:
            err('corrupt input ['+label+']')
            if opt.verbose:err('reason: comment mismatch')
        squash=opt.squash and opt.mode=='compress' and len(output)>len(data)
        if squash and opt.verbose:err('Output is larger than input')
        if fdout is not None:
            try:
                if info is not None and not opt.no_stat:
                    try:os.fchown(fdout,info.st_uid,info.st_gid)
                    except OSError:pass
                    os.fchmod(fdout,stat.S_IMODE(info.st_mode))
                    os.utime(fdout,ns=(info.st_atime_ns,info.st_mtime_ns))
                os.close(fdout);fdout=None
            except OSError as e:
                err('failed to close output file ['+output_name+']: '+e.strerror)
                return 1
        if squash:
            if output_name is not None:
                try:os.unlink(output_name)
                except OSError:pass
        elif opt.remove and input_name is not None:
            try:os.unlink(input_name)
            except OSError as e:
                err('failed to remove input file ['+input_name+']: '+e.strerror)
                return 1
    return 0

if __name__=='__main__':
    sys.exit(main())
