def population_cost(counts):
    total=sum(counts)
    nonzero=[x for x in counts if x]
    k=len(nonzero)
    if k<=1:return 12
    if k==2:return 20+total
    if k==3:return 28+2*total-max(nonzero)
    if k==4:
        s=sorted(nonzero,reverse=True)
        return 37+min(2*total,3*total-2*s[0]-s[1])
    w=BitWriter();t=write_tree(w,counts)
    return w.pos+sum(x*t.codes[i][0] for i,x in enumerate(counts) if x)


def distance_parameters(commands):
    best=None;result=(3,120)
    for p in range(4):
        for d in range(16):
            direct=d<<p
            counts=[0]*(16+direct+(48<<p));cache=[4,11,15,16];cost=0
            for start,ins,copy,dist,static in commands:
                if dist is None:continue
                dc,nb,ex=distance_code(dist,cache,p,direct,not static)
                sym,_,_=command_code(ins,copy,dc==0)
                if sym>=128:
                    cost+=nb;counts[dc]+=1
                if dc and not static:cache=[dist]+cache[:3]
            cost+=population_cost(counts)
            if best is None or cost<=best:
                best=cost;result=p,direct
    return result


def cluster_literals(data,commands,mode):
    hist=[[0]*256 for _ in range(64)]
    for start,ins,_,_,_ in commands:
        for p in range(start,start+ins):
            ctx=literal_context(mode,data[p-1] if p else 0,data[p-2] if p>1 else 0)
            hist[ctx][data[p]]+=1
    active=[i for i,h in enumerate(hist) if any(h)]
    if not active:return [0]*64,[[1]+[0]*255]
    costs={i:population_cost(hist[i]) for i in active}
    sets={i:[i] for i in active}
    # Greedily combine histograms using the cost of their prefix code.
    while len(active)>1:
        best=(0,None,None,None)
        for ia,a in enumerate(active):
            for b in active[ia+1:]:
                merged=[x+y for x,y in zip(hist[a],hist[b])]
                c=population_cost(merged)
                diff=c-costs[a]-costs[b]
                if diff<best[0]:best=(diff,a,b,merged)
        if best[1] is None:break
        _,a,b,h=best
        hist[a]=h;costs[a]=population_cost(h)
        sets[a]+=sets.pop(b);active.remove(b)
    group={}
    for i,a in enumerate(active):
        for x in sets[a]:group[x]=i
    mapping=[];prev=0
    for i in range(64):
        if i in group:prev=group[i]
        mapping.append(prev)
    return mapping,[hist[a] for a in active]


def write_context_map(w,mapping,number):
    write_uint8(w,number-1)
    if number==1:return
    mtf=list(range(number));seq=[]
    for v in mapping:
        i=mtf.index(v);seq.append(i);mtf.pop(i);mtf.insert(0,v)
    maxrun=0;i=0
    while i<len(seq):
        j=i+1
        if seq[i]==0:
            while j<len(seq) and seq[j]==0:j+=1
            maxrun=max(maxrun,j-i)
        i=j
    rle=min(6,maxrun.bit_length()-1) if maxrun else 0
    w.write(1,int(rle>0))
    if rle:w.write(4,rle-1)
    tokens=[];i=0
    while i<len(seq):
        if seq[i]:
            tokens.append((seq[i]+rle,0));i+=1
        else:
            j=i+1
            while j<len(seq) and seq[j]==0:j+=1
            count=j-i
            while count:
                p=min(rle,count.bit_length()-1)
                amount=min(count,(2<<p)-1)
                tokens.append((p,amount-(1<<p)))
                count-=amount
            i=j
    counts=[0]*(number+rle)
    for s,e in tokens:counts[s]+=1
    t=write_tree(w,counts)
    for s,e in tokens:
        t.write(w,s)
        if 0<s<=rle:w.write(s,e)
    w.write(1,1)
