// A small launcher for the independent, embedded implementation.
// The payload is original source assembled at build time, not a separate tool.
#include <cerrno>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fcntl.h>
#include <string>
#include <sys/syscall.h>
#include <unistd.h>
#include <vector>

#include "payload.inc"

int main(int argc, char** argv) {
    int fd = -1;
#ifdef SYS_memfd_create
    fd = static_cast<int>(syscall(SYS_memfd_create, "stream-codec-source", 0));
#endif
    if (fd == -1) {
        char name[] = "/tmp/stream-codec-XXXXXX";
        fd = mkstemp(name);
        if (fd != -1) unlink(name);
    }
    if (fd == -1) {
        std::fprintf(stderr, "unable to initialize application: %s\n", std::strerror(errno));
        return 1;
    }
    fcntl(fd, F_SETFD, 0);
    const char* p = program_source;
    size_t remaining = sizeof(program_source) - 1;
    while (remaining) {
        ssize_t n = write(fd, p, remaining);
        if (n < 0 && errno == EINTR) continue;
        if (n <= 0) { close(fd); return 1; }
        p += n;
        remaining -= static_cast<size_t>(n);
    }
    lseek(fd, 0, SEEK_SET);
    std::string path = "/proc/self/fd/" + std::to_string(fd);
    std::vector<char*> args;
    args.push_back(const_cast<char*>("python3"));
    args.push_back(const_cast<char*>("-B"));
    args.push_back(const_cast<char*>(path.c_str()));
    for (int i = 0; i < argc; ++i) args.push_back(argv[i]);
    args.push_back(nullptr);
    execvp("python3", args.data());
    std::fprintf(stderr, "unable to start Python 3: %s\n", std::strerror(errno));
    close(fd);
    return 1;
}
